def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.
    Each path starts at (1, 1) and ends at (N, N), moving only right or down.
    A cell's value can be collected at most once, even if both paths pass through it.
    """
    if N <= 0:
        return 0

    # Build grid with 1-indexed coordinates
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = val

    # Special case N == 1
    if N == 1:
        return grid[1][1]

    # Initialize DP array with negative infinity
    NEG = -10**18
    dp_prev = [[NEG] * (N + 1) for _ in range(N + 1)]
    dp_prev[1][1] = grid[1][1]

    # Iterate over steps t = 2 .. 2N
    for t in range(3, 2 * N + 1):
        dp_cur = [[NEG] * (N + 1) for _ in range(N + 1)]
        # i1 and i2 are row indices for the two paths
        for i1 in range(1, min(N, t - 1) + 1):
            j1 = t - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(1, min(N, t - 1) + 1):
                j2 = t - i2
                if j2 < 1 or j2 > N:
                    continue
                best = NEG
                # Consider all four combinations of previous moves
                for pi1, pi2 in ((i1 - 1, i2 - 1), (i1 - 1, i2), (i1, i2 - 1), (i1, i2)):
                    if pi1 < 1 or pi2 < 1:
                        continue
                    if dp_prev[pi1][pi2] > best:
                        best = dp_prev[pi1][pi2]
                if best == NEG:
                    continue
                add = grid[i1][j1]
                if i1 != i2 or j1 != j2:
                    add += grid[i2][j2]
                dp_cur[i1][i2] = best + add
        dp_prev = dp_cur

    return dp_prev[N][N] if dp_prev[N][N] != NEG else 0

def max_product(num_str: str, N: int, K: int) -> int:
    """
    Return the maximum product obtainable by inserting K multiplication signs into the
    numeric string `num_str` of length N. The string consists only of decimal digits.
    If the input is invalid (e.g., K > N-1 or negative), the function returns 0.
    """
    # Validate input length
    if not num_str:
        return 0
    if N != len(num_str):
        # Adjust N to actual length to avoid inconsistency
        N = len(num_str)
    if K < 0 or K > N - 1:
        return 0
    if K == 0:
        try:
            return int(num_str)
        except ValueError:
            return 0

    # Precompute integer values for all substrings
    # val[j][i] = int(num_str[j:i]) for 0 <= j < i <= N
    val = [[0] * (N + 1) for _ in range(N + 1)]
    for j in range(N):
        num = 0
        for i in range(j + 1, N + 1):
            num = num * 10 + (ord(num_str[i - 1]) - 48)
            val[j][i] = num

    # DP table: dp[i][k] = max product for prefix of length i with k cuts
    dp = [[None] * (K + 1) for _ in range(N + 1)]

    # Base case: no cuts
    for i in range(1, N + 1):
        dp[i][0] = val[0][i]

    # Fill DP
    for k in range(1, K + 1):
        # Need at least k+1 digits to place k cuts
        for i in range(k + 1, N + 1):
            max_prod = None
            # Last part starts at j, ends at i
            for j in range(k, i):
                prev = dp[j][k - 1]
                if prev is None:
                    continue
                prod = prev * val[j][i]
                if max_prod is None or prod > max_prod:
                    max_prod = prod
            dp[i][k] = max_prod

    result = dp[N][K]
    return result if result is not None else 0

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    """
    Optimize the placement of aisles in a classroom to minimize the amount of chatting between students.

    Args:
        M (int): The number of rows in the classroom.
        N (int): The number of columns in the classroom.
        K (int): The number of horizontal aisles to add.
        L (int): The number of vertical aisles to add.
        D (int): The number of chatting pairs in the classroom.
        chatting_pairs (list of tuples): A list of tuples, each containing the positions (Xi, Yi) and (Pi, Qi) of a chatting pair.

    Returns:
        (str, str): Two space-separated strings representing the optimal row and column indices for the aisles.
    """
    # Basic validation
    try:
        if not (isinstance(M, int) and M > 0 and isinstance(N, int) and N > 0):
            raise ValueError("M and N must be positive integers.")
        if not (isinstance(K, int) and 0 <= K <= M - 1):
            raise ValueError("K must be between 0 and M-1.")
        if not (isinstance(L, int) and 0 <= L <= N - 1):
            raise ValueError("L must be between 0 and N-1.")
        if not (isinstance(D, int) and D >= 0):
            raise ValueError("D must be non-negative.")
        if not isinstance(chatting_pairs, list):
            raise ValueError("chatting_pairs must be a list.")
        if len(chatting_pairs) != D:
            raise ValueError("Length of chatting_pairs does not match D.")
        for pair in chatting_pairs:
            if not (isinstance(pair, tuple) and len(pair) == 4):
                raise ValueError("Each chatting pair must be a tuple of four integers.")
            xi, yi, pi, qi = pair
            if not (1 <= xi <= M and 1 <= pi <= M and 1 <= yi <= N and 1 <= qi <= N):
                raise ValueError("Student positions out of bounds.")
    except Exception as e:
        raise ValueError(f"Invalid input: {e}")

    # Precompute which pairs are separated by each possible row and column aisle
    row_positions = list(range(1, M))  # aisle after row r
    col_positions = list(range(1, N))  # aisle after column c

    # For each row position, set of pair indices it separates
    row_separations = {r: set() for r in row_positions}
    # For each column position, set of pair indices it separates
    col_separations = {c: set() for c in col_positions}

    for idx, (xi, yi, pi, qi) in enumerate(chatting_pairs):
        # Row separation
        r_min = min(xi, pi)
        r_max = max(xi, pi)
        for r in range(r_min, r_max):
            if r in row_separations:
                row_separations[r].add(idx)
        # Column separation
        c_min = min(yi, qi)
        c_max = max(yi, qi)
        for c in range(c_min, c_max):
            if c in col_separations:
                col_separations[c].add(idx)

    # Helper to compute separated pairs for a set of rows
    def separated_by_rows(rows):
        s = set()
        for r in rows:
            s.update(row_separations[r])
        return s

    # Helper to compute separated pairs for a set of columns
    def separated_by_cols(cols):
        s = set()
        for c in cols:
            s.update(col_separations[c])
        return s

    # If no aisles to place, return empty strings
    if K == 0 and L == 0:
        return ("", "")

    # Generate all combinations of rows and columns
    from itertools import combinations

    best_rows = None
    best_cols = None
    best_count = -1

    # If K > 0, iterate over row combinations; else only one empty set
    row_combos = [()] if K == 0 else list(combinations(row_positions, K))
    col_combos = [()] if L == 0 else list(combinations(col_positions, L))

    for r_combo in row_combos:
        rows_set = set(r_combo)
        rows_separated = separated_by_rows(rows_set)
        for c_combo in col_combos:
            cols_set = set(c_combo)
            cols_separated = separated_by_cols(cols_set)
            total_separated = rows_separated | cols_separated
            count = len(total_separated)
            if count > best_count:
                best_count = count
                best_rows = sorted(rows_set)
                best_cols = sorted(cols_set)
            # If tie, keep the first found (lexicographically smallest due to iteration order)

    # Convert to space-separated strings
    row_str = " ".join(str(r) for r in best_rows) if best_rows else ""
    col_str = " ".join(str(c) for c in best_cols) if best_cols else ""

    return (row_str, col_str)

def polynomial_to_string(n: int, coeffs: list) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    The function takes in the highest degree `n` of the polynomial and a list of coefficients `coeffs`,
    which are ordered from the highest degree term to the constant term. It returns a string that
    represents the polynomial with the following rules:
    - Terms with a coefficient of zero are omitted.
    - The sign of each term is determined (+ for positive, - for negative), with no leading '+' for the first term.
    - The absolute value of the coefficient is shown unless it's 1 and the term includes the variable `x`.
    - The variable part is formatted based on its degree; `x^degree` for degree > 1, `x` for degree 1, and
      nothing for degree 0 (constant term).
    - Terms are joined without additional spaces, starting with the highest degree term.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    # Basic input validation
    if not isinstance(n, int):
        raise TypeError(f"n must be an integer, got {type(n).__name__}")
    if n < 0:
        raise ValueError(f"n must be non-negative, got {n}")
    if not isinstance(coeffs, list):
        raise TypeError(f"coeffs must be a list, got {type(coeffs).__name__}")
    if len(coeffs) != n + 1:
        raise ValueError(f"coeffs length must be n+1 ({n+1}), got {len(coeffs)}")
    for idx, c in enumerate(coeffs):
        if not isinstance(c, int):
            raise TypeError(f"coeffs[{idx}] must be an integer, got {type(c).__name__}")

    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue

        # Determine sign
        if not terms:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '-' if coeff < 0 else '+'

        abs_coeff = abs(coeff)

        # Determine coefficient string
        if abs_coeff == 1 and degree > 0:
            coeff_str = ''
        else:
            coeff_str = str(abs_coeff)

        # Determine variable part
        if degree > 1:
            var_str = f'x^{degree}'
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = ''

        term = f"{sign}{coeff_str}{var_str}"
        terms.append(term)

    if not terms:
        return '0'
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    # Basic validation: encoded and original must be of same length
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    reverse = {}

    for e_char, o_char in zip(encoded, original):
        # Check for consistency in forward mapping
        if e_char in mapping:
            if mapping[e_char] != o_char:
                return "Failed"
        else:
            mapping[e_char] = o_char
        # Check for consistency in reverse mapping (bijection)
        if o_char in reverse:
            if reverse[o_char] != e_char:
                return "Failed"
        else:
            reverse[o_char] = e_char

    # Ensure mapping covers all 26 uppercase letters
    if len(mapping) != 26:
        return "Failed"

    # Decode the message
    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded_chars.append(mapping[ch])

    return "".join(decoded_chars)

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to 10 steps. Returns minimum steps if possible, otherwise "NO ANSWER!".
    """
    try:
        if not isinstance(A, str) or not isinstance(B, str) or not isinstance(rules, list):
            return "NO ANSWER!"
        # Validate rules format
        for rule in rules:
            if not (isinstance(rule, tuple) and len(rule) == 2 and isinstance(rule[0], str) and isinstance(rule[1], str)):
                return "NO ANSWER!"
        if A == B:
            return 0
        from collections import deque
        visited = {A}
        queue = deque([(A, 0)])
        max_depth = 10
        while queue:
            current, steps = queue.popleft()
            if steps >= max_depth:
                continue
            next_steps = steps + 1
            for src, tgt in rules:
                start = 0
                while True:
                    idx = current.find(src, start)
                    if idx == -1:
                        break
                    new_str = current[:idx] + tgt + current[idx + len(src):]
                    if new_str == B:
                        return next_steps
                    if new_str not in visited:
                        visited.add(new_str)
                        queue.append((new_str, next_steps))
                    start = idx + 1
        return "NO ANSWER!"
    except Exception:
        return "NO ANSWER!"

def catalan_number(n: int) -> int:
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    dp = [0]*(n+1)
    dp[0] = 1
    for i in range(1, n+1):
        total = 0
        for j in range(i):
            total += dp[j]*dp[i-1-j]
        dp[i] = total
    return dp[n]
